    metrics::set_gauge(
        &metrics::GOSSIP_BEACON_BLOCK_SKIPPED_SLOTS,
        block
            .slot()
            .as_u64()
            .saturating_sub(1)
            .saturating_sub(parent_block.slot.into()) as i64,
