    24→/// An error occurred while validating a gossip blob.
    25→#[derive(Debug)]
    26→pub enum GossipBlobError {
    27→    /// The blob sidecar is from a slot that is later than the current slot (with respect to the
    28→    /// gossip clock disparity).
    29→    ///
    30→    /// ## Peer scoring
    31→    ///
    32→    /// Assuming the local clock is correct, the peer has sent an invalid message.
    33→    FutureSlot {
    34→        message_slot: Slot,
    35→        latest_permissible_slot: Slot,
    36→    },
    37→
    38→    /// There was an error whilst processing the blob. It is not known if it is
    39→    /// valid or invalid.
    40→    ///
    41→    /// ## Peer scoring
    42→    ///
    43→    /// We were unable to process this blob due to an internal error. It's
    44→    /// unclear if the blob is valid.
    45→    BeaconChainError(Box<BeaconChainError>),
    46→
    47→    /// The `BlobSidecar` was gossiped over an incorrect subnet.
    48→    ///
    49→    /// ## Peer scoring
    50→    ///
    51→    /// The blob is invalid or the peer is faulty.
    52→    InvalidSubnet { expected: u64, received: u64 },
    53→
    54→    /// The sidecar corresponds to a slot older than the finalized head slot.
    55→    ///
    56→    /// ## Peer scoring
    57→    ///
    58→    /// It's unclear if this blob is valid, but this blob is for a finalized slot and is
    59→    /// therefore useless to us.
    60→    PastFinalizedSlot {
    61→        blob_slot: Slot,
    62→        finalized_slot: Slot,
    63→    },
    64→
    65→    /// The proposer index specified in the sidecar does not match the locally computed
    66→    /// proposer index.
    67→    ///
    68→    /// ## Peer scoring
    69→    ///
    70→    /// The blob is invalid and the peer is faulty.
    71→    ProposerIndexMismatch { sidecar: usize, local: usize },
    72→
    73→    /// The proposal signature in invalid.
    74→    ///
    75→    /// ## Peer scoring
    76→    ///
    77→    /// The blob is invalid and the peer is faulty.
    78→    ProposalSignatureInvalid,
    79→
    80→    /// The proposal_index corresponding to blob.beacon_block_root is not known.
    81→    ///
    82→    /// ## Peer scoring
    83→    ///
    84→    /// The blob is invalid and the peer is faulty.
    85→    UnknownValidator(u64),
    86→
    87→    /// The provided blob is not from a later slot than its parent.
    88→    ///
    89→    /// ## Peer scoring
    90→    ///
    91→    /// The blob is invalid and the peer is faulty.
    92→    BlobIsNotLaterThanParent { blob_slot: Slot, parent_slot: Slot },
    93→
    94→    /// The provided blob's parent block is unknown.
    95→    ///
    96→    /// ## Peer scoring
    97→    ///
    98→    /// We cannot process the blob without validating its parent, the peer isn't necessarily faulty.
    99→    ParentUnknown { parent_root: Hash256 },
   100→
   101→    /// Invalid kzg commitment inclusion proof
   102→    /// ## Peer scoring
   103→    ///
   104→    /// The blob sidecar is invalid and the peer is faulty
   105→    InvalidInclusionProof,
   106→
   107→    /// A blob has already been seen for the given `(sidecar.block_root, sidecar.index)` tuple
   108→    /// over gossip or no gossip sources.
   109→    ///
   110→    /// ## Peer scoring
   111→    ///
   112→    /// The peer isn't faulty, but we do not forward it over gossip.
   113→    RepeatBlob {
   114→        proposer: u64,
   115→        slot: Slot,
   116→        index: u64,
   117→    },
   118→
   119→    /// The kzg verification failed.
   120→    ///
   121→    /// ## Peer scoring
   122→    ///
   123→    /// The blob sidecar is invalid and the peer is faulty.
   124→    KzgError(kzg::Error),
   125→
   126→    /// The pubkey cache timed out.
   127→    ///
   128→    /// ## Peer scoring
   129→    ///
   130→    /// The blob sidecar may be valid, this is an internal error.
   131→    PubkeyCacheTimeout,
   132→
   133→    /// The block conflicts with finalization, no need to propagate.
   134→    ///
   135→    /// ## Peer scoring
   136→    ///
   137→    /// It's unclear if this block is valid, but it conflicts with finality and shouldn't be
   138→    /// imported.
   139→    NotFinalizedDescendant { block_parent_root: Hash256 },
   140→}
