   372→/// Complete kzg verification for a list of `BlobSidecar`s.
   373→/// Returns an error if any of the `BlobSidecar`s fails kzg verification.
   374→///
   375→/// Note: This function should be preferred over calling `verify_kzg_for_blob`
   376→/// in a loop since this function kzg verifies a list of blobs more efficiently.
   377→#[instrument(skip_all, level = "debug")]
   378→pub fn verify_kzg_for_blob_list<'a, E: EthSpec, I>(
   379→    blob_iter: I,
   380→    kzg: &'a Kzg,
   381→) -> Result<(), KzgError>
   382→where
   383→    I: Iterator<Item = &'a Arc<BlobSidecar<E>>>,
   384→{
