   391→pub fn validate_blob_sidecar_for_gossip<T: BeaconChainTypes, O: ObservationStrategy>(
   392→    blob_sidecar: Arc<BlobSidecar<T::EthSpec>>,
   393→    subnet: u64,
   394→    chain: &BeaconChain<T>,
   395→) -> Result<GossipVerifiedBlob<T, O>, GossipBlobError> {
   396→    let blob_slot = blob_sidecar.slot();
   397→    let blob_index = blob_sidecar.index;
   398→    let block_parent_root = blob_sidecar.block_parent_root();
   399→    let blob_proposer_index = blob_sidecar.block_proposer_index();
   400→    let block_root = blob_sidecar.block_root();
   401→    let blob_epoch = blob_slot.epoch(T::EthSpec::slots_per_epoch());
   402→    let signed_block_header = &blob_sidecar.signed_block_header;
   403→
   404→    let seen_timestamp = chain.slot_clock.now_duration().unwrap_or_default();
   405→
   406→    // This condition is not possible if we have received the blob from the network
   407→    // since we only subscribe to `MaxBlobsPerBlock` subnets over gossip network.
   408→    // We include this check only for completeness.
   409→    // Getting this error would imply something very wrong with our networking decoding logic.
   410→    if blob_index >= chain.spec.max_blobs_per_block(blob_epoch) {
   411→        return Err(GossipBlobError::InvalidSubnet {
   412→            expected: subnet,
   413→            received: blob_index,
   414→        });
   415→    }
   416→
   417→    // Verify that the blob_sidecar was received on the correct subnet.
   418→    if blob_index != subnet {
   419→        return Err(GossipBlobError::InvalidSubnet {
   420→            expected: subnet,
   421→            received: blob_index,
   422→        });
   423→    }
   424→
   425→    // Verify that the sidecar is not from a future slot.
   426→    let latest_permissible_slot = chain
   427→        .slot_clock
   428→        .now_with_future_tolerance(chain.spec.maximum_gossip_clock_disparity())
   429→        .ok_or(BeaconChainError::UnableToReadSlot)?;
   430→    if blob_slot > latest_permissible_slot {
   431→        return Err(GossipBlobError::FutureSlot {
   432→            message_slot: blob_slot,
   433→            latest_permissible_slot,
   434→        });
   435→    }
   436→
   437→    // Verify that the sidecar slot is greater than the latest finalized slot
   438→    let latest_finalized_slot = chain
   439→        .head()
   440→        .finalized_checkpoint()
   441→        .epoch
   442→        .start_slot(T::EthSpec::slots_per_epoch());
   443→    if blob_slot <= latest_finalized_slot {
   444→        return Err(GossipBlobError::PastFinalizedSlot {
   445→            blob_slot,
   446→            finalized_slot: latest_finalized_slot,
   447→        });
   448→    }
   449→
   450→    // Verify that this is the first blob sidecar received for the tuple:
   451→    // (block_header.slot, block_header.proposer_index, blob_sidecar.index)
   452→    if chain
   453→        .observed_blob_sidecars
   454→        .read()
   455→        .proposer_is_known(&blob_sidecar)
   456→        .map_err(|e| GossipBlobError::BeaconChainError(Box::new(e.into())))?
   457→    {
   458→        return Err(GossipBlobError::RepeatBlob {
   459→            proposer: blob_proposer_index,
   460→            slot: blob_slot,
   461→            index: blob_index,
   462→        });
   463→    }
   464→
   465→    // Verify the inclusion proof in the sidecar
   466→    let _timer = metrics::start_timer(&metrics::BLOB_SIDECAR_INCLUSION_PROOF_VERIFICATION);
   467→    if !blob_sidecar.verify_blob_sidecar_inclusion_proof() {
   468→        return Err(GossipBlobError::InvalidInclusionProof);
   469→    }
   470→    drop(_timer);
   471→
   472→    let fork_choice = chain.canonical_head.fork_choice_read_lock();
   473→
   474→    // We have already verified that the blob is past finalization, so we can
   475→    // just check fork choice for the block's parent.
   476→    let Some(parent_block) = fork_choice.get_block(&block_parent_root) else {
   477→        return Err(GossipBlobError::ParentUnknown {
   478→            parent_root: block_parent_root,
   479→        });
   480→    };
   481→
   482→    // Do not process a blob that does not descend from the finalized root.
   483→    // We just loaded the parent_block, so we can be sure that it exists in fork choice.
   484→    if !fork_choice.is_finalized_checkpoint_or_descendant(block_parent_root) {
   485→        return Err(GossipBlobError::NotFinalizedDescendant { block_parent_root });
   486→    }
   487→    drop(fork_choice);
   488→
   489→    if parent_block.slot >= blob_slot {
   490→        return Err(GossipBlobError::BlobIsNotLaterThanParent {
   491→            blob_slot,
   492→            parent_slot: parent_block.slot,
   493→        });
   494→    }
   495→
   496→    let proposer_shuffling_root =
   497→        if parent_block.slot.epoch(T::EthSpec::slots_per_epoch()) == blob_epoch {
   498→            parent_block
   499→                .next_epoch_shuffling_id
   500→                .shuffling_decision_block
   501→        } else {
   502→            parent_block.root
   503→        };
   504→
   505→    let proposer_opt = chain
   506→        .beacon_proposer_cache
   507→        .lock()
   508→        .get_slot::<T::EthSpec>(proposer_shuffling_root, blob_slot);
   509→
   510→    let (proposer_index, fork) = if let Some(proposer) = proposer_opt {
   511→        (proposer.index, proposer.fork)
   512→    } else {
   513→        debug!(
   514→            %block_root,
   515→            %blob_index,
   516→            "Proposer shuffling cache miss for blob verification"
   517→        );
   518→        let (parent_state_root, mut parent_state) = chain
   519→            .store
   520→            .get_advanced_hot_state(block_parent_root, blob_slot, parent_block.state_root)
   521→            .map_err(|e| GossipBlobError::BeaconChainError(Box::new(e.into())))?
   522→            .ok_or_else(|| {
   523→                BeaconChainError::DBInconsistent(format!(
   524→                    "Missing state for parent block {block_parent_root:?}",
   525→                ))
   526→            })?;
   527→
   528→        let state = cheap_state_advance_to_obtain_committees::<_, GossipBlobError>(
   529→            &mut parent_state,
   530→            Some(parent_state_root),
   531→            blob_slot,
   532→            &chain.spec,
   533→        )?;
   534→
   535→        let epoch = state.current_epoch();
   536→        let proposers = state.get_beacon_proposer_indices(epoch, &chain.spec)?;
   537→        let proposer_index = *proposers
   538→            .get(blob_slot.as_usize() % T::EthSpec::slots_per_epoch() as usize)
   539→            .ok_or_else(|| BeaconChainError::NoProposerForSlot(blob_slot))?;
   540→
   541→        // Prime the proposer shuffling cache with the newly-learned value.
   542→        chain.beacon_proposer_cache.lock().insert(
   543→            blob_epoch,
   544→            proposer_shuffling_root,
   545→            proposers,
   546→            state.fork(),
   547→        )?;
   548→        (proposer_index, state.fork())
   549→    };
   550→
   551→    // Signature verify the signed block header.
   552→    let signature_is_valid = {
   553→        let pubkey_cache =
   554→            get_validator_pubkey_cache(chain).map_err(|_| GossipBlobError::PubkeyCacheTimeout)?;
   555→
   556→        let pubkey = pubkey_cache
   557→            .get(proposer_index)
   558→            .ok_or_else(|| GossipBlobError::UnknownValidator(proposer_index as u64))?;
   559→        signed_block_header.verify_signature::<T::EthSpec>(
   560→            pubkey,
   561→            &fork,
   562→            chain.genesis_validators_root,
   563→            &chain.spec,
   564→        )
   565→    };
   566→
   567→    if !signature_is_valid {
   568→        return Err(GossipBlobError::ProposalSignatureInvalid);
   569→    }
   570→
   571→    if proposer_index != blob_proposer_index as usize {
   572→        return Err(GossipBlobError::ProposerIndexMismatch {
   573→            sidecar: blob_proposer_index as usize,
   574→            local: proposer_index,
   575→        });
   576→    }
   577→
   578→    // Kzg verification for gossip blob sidecar
   579→    let kzg = chain.kzg.as_ref();
   580→
   581→    let kzg_verified_blob = KzgVerifiedBlob::new(blob_sidecar.clone(), kzg, seen_timestamp)
   582→        .map_err(GossipBlobError::KzgError)?;
   583→    let blob_sidecar = &kzg_verified_blob.blob;
   584→
   585→    chain
   586→        .observed_slashable
   587→        .write()
   588→        .observe_slashable(
   589→            blob_sidecar.slot(),
   590→            blob_sidecar.block_proposer_index(),
   591→            block_root,
   592→        )
   593→        .map_err(|e| GossipBlobError::BeaconChainError(Box::new(e.into())))?;
   594→
   595→    if O::observe() {
   596→        observe_gossip_blob(&kzg_verified_blob.blob, chain)?;
   597→    }
   598→
   599→    Ok(GossipVerifiedBlob {
   600→        block_root,
   601→        blob: kzg_verified_blob,
   602→        _phantom: PhantomData,
   603→    })
   604→}
   605→
   606→pub fn observe_gossip_blob<T: BeaconChainTypes>(
   607→    blob_sidecar: &BlobSidecar<T::EthSpec>,
   608→    chain: &BeaconChain<T>,
   609→) -> Result<(), GossipBlobError> {
   610→    // Now the signature is valid, store the proposal so we don't accept another blob sidecar
   611→    // with the same `BlobIdentifier`.  It's important to double-check that the proposer still
   612→    // hasn't been observed so we don't have a race-condition when verifying two blocks
   613→    // simultaneously.
   614→    //
   615→    // Note: If this BlobSidecar goes on to fail full verification, we do not evict it from the
   616→    // seen_cache as alternate blob_sidecars for the same identifier can still be retrieved over
   617→    // rpc. Evicting them from this cache would allow faster propagation over gossip. So we
   618→    // allow retrieval of potentially valid blocks over rpc, but try to punish the proposer for
   619→    // signing invalid messages. Issue for more background
   620→    // https://github.com/ethereum/consensus-specs/issues/3261
   621→    if chain
   622→        .observed_blob_sidecars
   623→        .write()
   624→        .observe_sidecar(blob_sidecar)
   625→        .map_err(|e| GossipBlobError::BeaconChainError(Box::new(e.into())))?
   626→    {
   627→        return Err(GossipBlobError::RepeatBlob {
   628→            proposer: blob_sidecar.block_proposer_index(),
   629→            slot: blob_sidecar.slot(),
   630→            index: blob_sidecar.index,
   631→        });
   632→    }
   633→    Ok(())
   634→}
   635→
   636→/// Returns the canonical root of the given `blob`.
   637→///
   638→/// Use this function to ensure that we report the blob hashing time Prometheus metric.
   639→pub fn get_blob_root<E: EthSpec>(blob: &BlobSidecar<E>) -> Hash256 {
   640→    let blob_root_timer = metrics::start_timer(&metrics::BLOCK_PROCESSING_BLOB_ROOT);
   641→
   642→    let blob_root = blob.tree_hash_root();
   643→
   644→    metrics::stop_timer(blob_root_timer);
   645→
   646→    blob_root
   647→}
